window.CarePlusOriginalViews["admin/scan_qr.html"]=function(c,p){let html="";html+="<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>QR Code Scanner - Patient Check-in</title>\r\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\r\n    <script src=\"https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js\"></script>\r\n    <style>\r\n        * {\r\n            margin: 0;\r\n            padding: 0;\r\n            box-sizing: border-box;\r\n        }\r\n        \r\n        body {\r\n            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\r\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\r\n            min-height: 100vh;\r\n            padding: 2rem;\r\n        }\r\n        \r\n        .scanner-container {\r\n            background: white;\r\n            border-radius: 24px;\r\n            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\r\n            padding: 3rem;\r\n            max-width: 900px;\r\n            margin: 0 auto;\r\n            animation: slideUp 0.5s ease;\r\n        }\r\n        \r\n        @keyframes slideUp {\r\n            from {\r\n                opacity: 0;\r\n                transform: translateY(30px);\r\n            }\r\n            to {\r\n                opacity: 1;\r\n                transform: translateY(0);\r\n            }\r\n        }\r\n        \r\n        .scanner-header {\r\n            text-align: center;\r\n            margin-bottom: 2rem;\r\n        }\r\n        \r\n        .scanner-header h1 {\r\n            font-size: 2.5rem;\r\n            color: #667eea;\r\n            margin-bottom: 0.5rem;\r\n            font-weight: 800;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            gap: 1rem;\r\n        }\r\n        \r\n        .scanner-header p {\r\n            color: #666;\r\n            font-size: 1.1rem;\r\n            font-weight: 500;\r\n        }\r\n        \r\n        .scan-mode-toggle {\r\n            display: flex;\r\n            gap: 1rem;\r\n            margin-bottom: 2rem;\r\n            background: #f5f5f5;\r\n            padding: 0.5rem;\r\n            border-radius: 12px;\r\n        }\r\n        \r\n        .mode-btn {\r\n            flex: 1;\r\n            padding: 1rem;\r\n            border: none;\r\n            background: transparent;\r\n            border-radius: 8px;\r\n            font-size: 1rem;\r\n            font-weight: 700;\r\n            cursor: pointer;\r\n            transition: all 0.3s;\r\n            color: #666;\r\n        }\r\n        \r\n        .mode-btn.active {\r\n            background: linear-gradient(135deg, #667eea, #764ba2);\r\n            color: white;\r\n            box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);\r\n        }\r\n        \r\n        .scan-section {\r\n            display: none;\r\n        }\r\n        \r\n        .scan-section.active {\r\n            display: block;\r\n        }\r\n        \r\n        /* Camera Scanner */\r\n        #qr-reader {\r\n            border-radius: 12px;\r\n            overflow: hidden;\r\n            margin-bottom: 1.5rem;\r\n        }\r\n        \r\n        #qr-reader video {\r\n            border-radius: 12px;\r\n        }\r\n        \r\n        /* Manual Input */\r\n        .scan-input-group {\r\n            position: relative;\r\n            margin-bottom: 1.5rem;\r\n        }\r\n        \r\n        .scan-input-group i {\r\n            position: absolute;\r\n            left: 1.5rem;\r\n            top: 50%;\r\n            transform: translateY(-50%);\r\n            color: #667eea;\r\n            font-size: 1.5rem;\r\n        }\r\n        \r\n        #qrCodeInput {\r\n            width: 100%;\r\n            padding: 1.2rem 1.5rem 1.2rem 4rem;\r\n            border: 3px solid #e0e0e0;\r\n            border-radius: 12px;\r\n            font-size: 1.1rem;\r\n            transition: all 0.3s;\r\n            font-family: 'Courier New', monospace;\r\n            letter-spacing: 2px;\r\n            text-transform: uppercase;\r\n        }\r\n        \r\n        #qrCodeInput:focus {\r\n            outline: none;\r\n            border-color: #667eea;\r\n            box-shadow: 0 0 0 4px rgba(102, 126, 234, 0.1);\r\n        }\r\n        \r\n        .scan-btn {\r\n            width: 100%;\r\n            padding: 1.2rem;\r\n            background: linear-gradient(135deg, #667eea, #764ba2);\r\n            color: white;\r\n            border: none;\r\n            border-radius: 12px;\r\n            font-size: 1.1rem;\r\n            font-weight: 700;\r\n            cursor: pointer;\r\n            transition: all 0.3s;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            gap: 0.75rem;\r\n        }\r\n        \r\n        .scan-btn:hover {\r\n            transform: translateY(-2px);\r\n            box-shadow: 0 10px 30px rgba(102, 126, 234, 0.4);\r\n        }\r\n        \r\n        .scan-btn:disabled {\r\n            opacity: 0.6;\r\n            cursor: not-allowed;\r\n            transform: none;\r\n        }\r\n        \r\n        /* Result Container */\r\n        .result-container {\r\n            margin-top: 2rem;\r\n            padding: 2rem;\r\n            border-radius: 16px;\r\n            display: none;\r\n            animation: fadeIn 0.5s ease;\r\n        }\r\n        \r\n        @keyframes fadeIn {\r\n            from { opacity: 0; transform: translateY(20px); }\r\n            to { opacity: 1; transform: translateY(0); }\r\n        }\r\n        \r\n        .result-container.success {\r\n            background: linear-gradient(135deg, #d4edda, #c3e6cb);\r\n            border: 3px solid #28a745;\r\n        }\r\n        \r\n        .result-container.error {\r\n            background: linear-gradient(135deg, #f8d7da, #f5c6cb);\r\n            border: 3px solid #dc3545;\r\n        }\r\n        \r\n        .result-container.warning {\r\n            background: linear-gradient(135deg, #fff3cd, #ffeaa7);\r\n            border: 3px solid #ffc107;\r\n        }\r\n        \r\n        .result-header {\r\n            font-size: 1.8rem;\r\n            font-weight: 800;\r\n            margin-bottom: 1.5rem;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 0.75rem;\r\n        }\r\n        \r\n        .result-header.success { color: #155724; }\r\n        .result-header.error { color: #721c24; }\r\n        .result-header.warning { color: #856404; }\r\n        \r\n        .result-details {\r\n            display: grid;\r\n            gap: 1rem;\r\n        }\r\n        \r\n        .detail-row {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: flex-start;\r\n            padding: 1rem;\r\n            background: rgba(255, 255, 255, 0.8);\r\n            border-radius: 10px;\r\n            gap: 1rem;\r\n        }\r\n        \r\n        .detail-label {\r\n            font-weight: 700;\r\n            color: #424242;\r\n            min-width: 180px;\r\n        }\r\n        \r\n        .detail-value {\r\n            color: #666;\r\n            text-align: right;\r\n            flex: 1;\r\n            font-weight: 600;\r\n        }\r\n        \r\n        .close-result-btn {\r\n            margin-top: 1.5rem;\r\n            width: 100%;\r\n            padding: 1rem;\r\n            background: rgba(0, 0, 0, 0.1);\r\n            border: none;\r\n            border-radius: 10px;\r\n            font-weight: 700;\r\n            cursor: pointer;\r\n            transition: all 0.3s;\r\n        }\r\n        \r\n        .close-result-btn:hover {\r\n            background: rgba(0, 0, 0, 0.2);\r\n        }\r\n        \r\n        .back-btn {\r\n            margin-top: 2rem;\r\n            text-align: center;\r\n        }\r\n        \r\n        .back-btn a {\r\n            color: #667eea;\r\n            text-decoration: none;\r\n            font-weight: 700;\r\n            font-size: 1rem;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 0.5rem;\r\n            transition: all 0.3s;\r\n            padding: 0.75rem 1.5rem;\r\n            border-radius: 10px;\r\n        }\r\n        \r\n        .back-btn a:hover {\r\n            background: rgba(102, 126, 234, 0.1);\r\n            gap: 0.75rem;\r\n        }\r\n        \r\n        .scan-history {\r\n            margin-top: 2rem;\r\n            padding: 1.5rem;\r\n            background: #f8f9fa;\r\n            border-radius: 12px;\r\n        }\r\n        \r\n        .scan-history h3 {\r\n            color: #424242;\r\n            margin-bottom: 1rem;\r\n            font-size: 1.2rem;\r\n        }\r\n        \r\n        .scan-count {\r\n            color: #667eea;\r\n            font-size: 2rem;\r\n            font-weight: 800;\r\n        }\r\n        \r\n        @media (max-width: 768px) {\r\n            .scanner-container {\r\n                padding: 2rem 1.5rem;\r\n            }\r\n            \r\n            .scanner-header h1 {\r\n                font-size: 2rem;\r\n            }\r\n            \r\n            .detail-row {\r\n                flex-direction: column;\r\n            }\r\n            \r\n            .detail-label {\r\n                min-width: auto;\r\n            }\r\n            \r\n            .detail-value {\r\n                text-align: left;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"scanner-container\">\r\n        <div class=\"scanner-header\">\r\n            <h1><i class=\"fas fa-qrcode\"></i> QR Code Scanner</h1>\r\n            <p>Scan patient appointment QR code for check-in</p>\r\n        </div>\r\n        \r\n        <!-- Mode Toggle -->\r\n        <div class=\"scan-mode-toggle\">\r\n            <button class=\"mode-btn active\" onclick=\"switchMode('camera')\">\r\n                <i class=\"fas fa-camera\"></i> Camera Scanner\r\n            </button>\r\n            <button class=\"mode-btn\" onclick=\"switchMode('manual')\">\r\n                <i class=\"fas fa-keyboard\"></i> Manual Input\r\n            </button>\r\n        </div>\r\n        \r\n        <!-- Camera Scanner Section -->\r\n        <div id=\"cameraSection\" class=\"scan-section active\">\r\n            <div id=\"qr-reader\" style=\"width: 100%;\"></div>\r\n            <p style=\"text-align: center; color: #666; margin-top: 1rem;\">\r\n                <i class=\"fas fa-info-circle\"></i> Position the QR code within the camera frame\r\n            </p>\r\n        </div>\r\n        \r\n        <!-- Manual Input Section -->\r\n        <div id=\"manualSection\" class=\"scan-section\">\r\n            <form id=\"scanForm\">\r\n                <div class=\"scan-input-group\">\r\n                    <i class=\"fas fa-qrcode\"></i>\r\n                    <input type=\"text\" \r\n                           id=\"qrCodeInput\" \r\n                           name=\"qr_code\" \r\n                           placeholder=\"APT-XXXXXXXXXXXX\" \r\n                           autocomplete=\"off\"\r\n                           maxlength=\"255\">\r\n                </div>\r\n                \r\n                <button type=\"submit\" class=\"scan-btn\">\r\n                    <i class=\"fas fa-search\"></i>\r\n                    <span>Scan & Check In</span>\r\n                </button>\r\n            </form>\r\n        </div>\r\n        \r\n        <!-- Result Container -->\r\n        <div id=\"resultContainer\" class=\"result-container\"></div>\r\n        \r\n        <!-- Scan History -->\r\n        <div class=\"scan-history\">\r\n            <h3><i class=\"fas fa-history\"></i> Today's Check-ins</h3>\r\n            <div class=\"scan-count\" id=\"scanCount\">0</div>\r\n        </div>\r\n        \r\n        <div class=\"back-btn\">\r\n            <a href=\"dashboard.php\">\r\n                <i class=\"fas fa-arrow-left\"></i> Back to Dashboard\r\n            </a>\r\n        </div>\r\n    </div>\r\n    \r\n    <script>\r\n        let html5QrCode = null;\r\n        let scanCount = 0;\r\n        \r\n        // Initialize camera scanner\r\n        function initCameraScanner() {\r\n            if (html5QrCode) return;\r\n            \r\n            html5QrCode = new Html5Qrcode(\"qr-reader\");\r\n            \r\n            Html5Qrcode.getCameras().then(cameras => {\r\n                if (cameras && cameras.length) {\r\n                    const cameraId = cameras[cameras.length - 1].id; // Use back camera\r\n                    \r\n                    html5QrCode.start(\r\n                        cameraId,\r\n                        {\r\n                            fps: 10,\r\n                            qrbox: { width: 250, height: 250 }\r\n                        },\r\n                        (decodedText, decodedResult) => {\r\n                            console.log('QR Code detected:', decodedText);\r\n                            processQRCode(decodedText);\r\n                            \r\n                            // Stop scanning temporarily\r\n                            html5QrCode.pause();\r\n                            setTimeout(() => {\r\n                                if (html5QrCode.isScanning) {\r\n                                    html5QrCode.resume();\r\n                                }\r\n                            }, 3000);\r\n                        },\r\n                        (errorMessage) => {\r\n                            // Scanning error (ignore)\r\n                        }\r\n                    ).catch(err => {\r\n                        console.error('Unable to start camera:', err);\r\n                        alert('Unable to access camera. Please use manual input instead.');\r\n                    });\r\n                }\r\n            }).catch(err => {\r\n                console.error('Error getting cameras:', err);\r\n            });\r\n        }\r\n        \r\n        // Switch between camera and manual mode\r\n        function switchMode(mode) {\r\n            const cameraSec = document.getElementById('cameraSection');\r\n            const manualSec = document.getElementById('manualSection');\r\n            const modeBtns = document.querySelectorAll('.mode-btn');\r\n            \r\n            modeBtns.forEach(btn => btn.classList.remove('active'));\r\n            \r\n            if (mode === 'camera') {\r\n                cameraSec.classList.add('active');\r\n                manualSec.classList.remove('active');\r\n                modeBtns[0].classList.add('active');\r\n                initCameraScanner();\r\n            } else {\r\n                cameraSec.classList.remove('active');\r\n                manualSec.classList.add('active');\r\n                modeBtns[1].classList.add('active');\r\n                \r\n                // Stop camera\r\n                if (html5QrCode && html5QrCode.isScanning) {\r\n                    html5QrCode.stop();\r\n                }\r\n                \r\n                document.getElementById('qrCodeInput').focus();\r\n            }\r\n        }\r\n        \r\n        // Manual form submission\r\n        const scanForm = document.getElementById('scanForm');\r\n        scanForm.addEventListener('submit', async function(e) {\r\n            e.preventDefault();\r\n            const qrCode = document.getElementById('qrCodeInput').value.trim();\r\n            \r\n            if (!qrCode) {\r\n                showResult('error', 'Please enter a QR code', {});\r\n                return;\r\n            }\r\n            \r\n            await processQRCode(qrCode);\r\n            document.getElementById('qrCodeInput').value = '';\r\n        });\r\n        \r\n        // Process QR code\r\n        async function processQRCode(qrCode) {\r\n            const submitBtn = scanForm.querySelector('.scan-btn');\r\n            const originalHTML = submitBtn.innerHTML;\r\n            submitBtn.disabled = true;\r\n            submitBtn.innerHTML = '<i class=\"fas fa-spinner fa-spin\"></i> Processing...';\r\n            \r\n            try {\r\n                const formData = new FormData();\r\n                formData.append('qr_code', qrCode);\r\n                \r\n                const response = await fetch('scan_qr.php', {\r\n                    method: 'POST',\r\n                    body: formData\r\n                });\r\n                \r\n                const data = await response.json();\r\n                \r\n                if (data.success) {\r\n                    showResult('success', data.message, data.data);\r\n                    scanCount++;\r\n                    document.getElementById('scanCount').textContent = scanCount;\r\n                    \r\n                    // Play success sound (optional)\r\n                    playSound('success');\r\n                } else {\r\n                    showResult(data.message.includes('⚠️') ? 'warning' : 'error', data.message, data.data || {});\r\n                    playSound('error');\r\n                }\r\n            } catch (error) {\r\n                console.error('Error:', error);\r\n                showResult('error', 'Failed to process QR code. Please try again.', {});\r\n                playSound('error');\r\n            } finally {\r\n                submitBtn.disabled = false;\r\n                submitBtn.innerHTML = originalHTML;\r\n            }\r\n        }\r\n        \r\n        // Show result\r\n        function showResult(type, message, data) {\r\n            const resultContainer = document.getElementById('resultContainer');\r\n            resultContainer.className = 'result-container ' + type;\r\n            resultContainer.style.display = 'block';\r\n            \r\n            let html = `<div class=\"result-header ${type}\">${message}</div>`;\r\n            \r\n            if (data && Object.keys(data).length > 0) {\r\n                html += '<div class=\"result-details\">';\r\n                \r\n                for (const [key, value] of Object.entries(data)) {\r\n                    html += `\r\n                        <div class=\"detail-row\">\r\n                            <span class=\"detail-label\">${key}:</span>\r\n                            <span class=\"detail-value\">${value}</span>\r\n                        </div>\r\n                    `;\r\n                }\r\n                \r\n                html += '</div>';\r\n            }\r\n            \r\n            html += `\r\n                <button class=\"close-result-btn\" onclick=\"closeResult()\">\r\n                    <i class=\"fas fa-times\"></i> Close\r\n                </button>\r\n            `;\r\n            \r\n            resultContainer.innerHTML = html;\r\n            resultContainer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\r\n        }\r\n        \r\n        // Close result\r\n        function closeResult() {\r\n            const resultContainer = document.getElementById('resultContainer');\r\n            resultContainer.style.display = 'none';\r\n            \r\n            // Resume camera if in camera mode\r\n            const cameraSection = document.getElementById('cameraSection');\r\n            if (cameraSection.classList.contains('active') && html5QrCode) {\r\n                if (html5QrCode.getState() === Html5QrcodeScannerState.PAUSED) {\r\n                    html5QrCode.resume();\r\n                }\r\n            }\r\n        }\r\n        \r\n        // Play sound\r\n        function playSound(type) {\r\n            const audioContext = new (window.AudioContext || window.webkitAudioContext)();\r\n            const oscillator = audioContext.createOscillator();\r\n            const gainNode = audioContext.createGain();\r\n            \r\n            oscillator.connect(gainNode);\r\n            gainNode.connect(audioContext.destination);\r\n            \r\n            if (type === 'success') {\r\n                oscillator.frequency.value = 800;\r\n                gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);\r\n            } else {\r\n                oscillator.frequency.value = 400;\r\n                gainNode.gain.setValueAtTime(0.2, audioContext.currentTime);\r\n            }\r\n            \r\n            oscillator.start(audioContext.currentTime);\r\n            oscillator.stop(audioContext.currentTime + 0.1);\r\n        }\r\n        \r\n        // Initialize on page load\r\n        window.addEventListener('load', () => {\r\n            initCameraScanner();\r\n        });\r\n        \r\n        // Cleanup on page unload\r\n        window.addEventListener('beforeunload', () => {\r\n            if (html5QrCode && html5QrCode.isScanning) {\r\n                html5QrCode.stop();\r\n            }\r\n        });\r\n    </script>\r\n</body>\r\n</html>\n";;return html;};
